"""Writes domicile_layer.js as a C++ header holding `kDomicileLayer`.

  make_domicile_layer.py <domicile_layer.js> <domicile_layer.h>

As a byte array rather than a string literal, which compilers cap in length.
The layer is ASCII (codegen/generate-engine-layer.ts escapes the rest), and
this refuses anything else, since Blink reads the text as Latin-1.
"""

import sys


def main(source, header):
    with open(source, 'rb') as layer:
        text = layer.read()
    if any(byte > 0x7f for byte in text):
        sys.exit('%s is not ASCII; regenerate it' % source)
    rows = [
        ','.join(str(byte) for byte in text[start:start + 32])
        for start in range(0, len(text), 32)
    ]
    with open(header, 'w') as out:
        out.write('// Generated by make_domicile_layer.py. Do not edit.\n\n')
        out.write('#ifndef THIRD_PARTY_BLINK_RENDERER_MODULES_DOMICILE_'
                  'DOMICILE_LAYER_H_\n')
        out.write('#define THIRD_PARTY_BLINK_RENDERER_MODULES_DOMICILE_'
                  'DOMICILE_LAYER_H_\n\n')
        out.write('namespace blink {\n\n')
        out.write('// domicile_layer.js, NUL-terminated.\n')
        out.write('inline constexpr char kDomicileLayer[] = {\n')
        for row in rows:
            out.write('    %s,\n' % row)
        out.write('    0};\n\n')
        out.write('}  // namespace blink\n\n')
        out.write('#endif  // THIRD_PARTY_BLINK_RENDERER_MODULES_DOMICILE_'
                  'DOMICILE_LAYER_H_\n')


if __name__ == '__main__':
    main(*sys.argv[1:])
